<?php $e=fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8'); $st=$order['status']; ?>
<a class="btn btn-outline" href="<?= base_url('index.php?c=laboratory') ?>">Kembali ke Daftar Order</a><h1 style="color:var(--blue-900)">Pemeriksaan Laboratorium</h1>
<div class="card" style="padding:20px;margin:20px 0"><h2 style="font-size:18px"><?= $e($order['patient_name']) ?> · RM <?= $e($order['no_rm']) ?></h2><p>Order <b><?= $e($order['order_number']) ?></b> · <?= $e($order['clinical_priority']) ?> · <span class="badge badge-primary"><?= $e($st) ?></span></p><p>Dokter pengirim: <?= $e($order['doctor_name']) ?> · Catatan: <?= $e($order['clinical_notes']) ?></p><p>Alur: penerimaan & verifikasi → pemeriksaan & input → tinjauan & validasi → hasil valid → simpan & cetak.</p></div>
<?php if ($st==='PENDING'): ?>
<div class="card" style="padding:20px"><h2 style="font-size:17px">Verifikasi pasien dan permintaan</h2><ul><?php foreach ($items as $item): ?><li><?= $e($item['test_name']) ?></li><?php endforeach; ?></ul>
<?php if ($canEdit): ?><form method="post" action="<?= base_url('index.php?c=laboratory&a=process') ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$order['revision'] ?>"><label class="form-label" for="verify-rm">Ketik nomor RM setelah mencocokkan identitas</label><input id="verify-rm" class="form-control" name="no_rm" required autocomplete="off"><label style="display:block;margin:14px 0"><input type="checkbox" name="verified" value="1" required> Identitas pasien, permintaan, jenis pemeriksaan, dan sampel sudah sesuai.</label><button class="btn btn-primary" type="submit">Verifikasi dan Mulai Pemeriksaan</button></form><?php else: ?><p>Analis laboratorium melakukan verifikasi dan pemeriksaan.</p><?php endif; ?></div>
<?php else: ?>
<?php if ($st==='PROCESS' && !empty($order['review_notes'])): ?><div class="alert alert-warning">Perbaikan diperlukan: <?= $e($order['review_notes']) ?></div><?php endif; ?>
<div class="card" style="padding:20px"><h2 style="font-size:17px"><?= $st==='PROCESS'?'Input Hasil Pemeriksaan':($st==='REVIEW'?'Tinjau Hasil Sebelum Validasi':'Hasil Pemeriksaan') ?></h2>
<?php if ($st==='PROCESS' && $canEdit): ?><form method="post" action="<?= base_url('index.php?c=laboratory&a=saveResult') ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$order['revision'] ?>"><?php endif; ?>
<div class="table-responsive"><table class="table"><thead><tr><th>Pemeriksaan</th><th>Hasil *</th><th>Satuan</th><th>Nilai rujukan</th><th>Flag</th><th>Catatan</th></tr></thead><tbody>
<?php foreach ($items as $item): $i=$input[$item['id']] ?? []; ?><tr><td><?= $e($item['test_name']) ?></td>
<?php if ($st==='PROCESS' && $canEdit): ?>
<?php foreach (['result_value'=>[$item['result_value'],100],'unit'=>[$item['result_unit'] ?? $item['default_unit'],30],'normal_range'=>[$item['result_normal_range'] ?? $item['default_normal_range'],100]] as $key=>[$default,$max]): ?><td><input aria-label="<?= $e($item['test_name'].' '.$key) ?>" class="form-control" name="results[<?= (int)$item['id'] ?>][<?= $key ?>]" value="<?= $e($i[$key] ?? $default) ?>" maxlength="<?= $max ?>" <?= $key==='result_value'?'required':'' ?>></td><?php endforeach; ?>
<td><select aria-label="Flag <?= $e($item['test_name']) ?>" class="form-control" name="results[<?= (int)$item['id'] ?>][result_flag]"><?php foreach (['NORMAL','HIGH','LOW','CRITICAL'] as $flag): ?><option <?= ($i['result_flag'] ?? $item['result_flag'] ?? 'NORMAL')===$flag?'selected':'' ?>><?= $flag ?></option><?php endforeach; ?></select></td><td><input aria-label="Catatan <?= $e($item['test_name']) ?>" class="form-control" name="results[<?= (int)$item['id'] ?>][analyst_notes]" value="<?= $e($i['analyst_notes'] ?? $item['analyst_notes']) ?>"></td>
<?php else: ?><td><b><?= $e($item['result_value'] ?? '-') ?></b></td><td><?= $e($item['result_unit'] ?? '-') ?></td><td><?= $e($item['result_normal_range'] ?? '-') ?></td><td><?= $e($item['result_flag'] ?? '-') ?></td><td><?= $e($item['analyst_notes'] ?? '-') ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div>
<?php if ($st==='PROCESS' && $canEdit): ?><button class="btn btn-primary" type="submit">Tinjau hasil pemeriksaan</button></form><?php endif; ?>
<?php if ($st==='REVIEW' && $canEdit): ?><p>Periksa kembali identitas pasien, order, kelengkapan, dan nilai hasil sebelum validasi.</p>
<form method="post" action="<?= base_url('index.php?c=laboratory&a=validateResult') ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$order['revision'] ?>"><label style="display:block;margin:14px 0"><input type="checkbox" name="confirmed" value="1" required> Identitas pasien, order, kelengkapan, dan nilai hasil pemeriksaan telah saya periksa dan sesuai.</label><button class="btn btn-primary" name="decision" value="approve" type="submit">Validasi hasil pemeriksaan</button></form>
<details style="margin-top:20px"><summary>Hasil tidak sesuai — perbaiki hasil</summary><form method="post" action="<?= base_url('index.php?c=laboratory&a=validateResult') ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$order['revision'] ?>"><label for="reason" class="form-label">Alasan perbaikan</label><textarea id="reason" class="form-control" name="reason" required></textarea><button style="margin-top:12px" class="btn btn-outline" name="decision" value="return" type="submit">Kembali ke input hasil</button></form></details><?php endif; ?>
<?php if ($st==='VALIDATED' && $canEdit): ?><p>Hasil telah dinyatakan valid dan terkait dengan pasien serta order ini. Simpan hasil agar tersedia pada rekam medis dan dapat dicetak.</p><form method="post" action="<?= base_url('index.php?c=laboratory&a=finalizeResult') ?>"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$order['revision'] ?>"><button class="btn btn-primary" type="submit"><i data-lucide="save"></i> Simpan hasil pemeriksaan</button></form><?php endif; ?>
<?php if ($st==='VALID'): ?><p>Divalidasi pada <?= format_datetime_id($order['validated_at'] ?? $order['completed_at']) ?>. Disimpan oleh <?= $e($order['analyst_name']) ?> pada <?= format_datetime_id($order['completed_at']) ?>. Hasil final dikunci.</p><a class="btn btn-primary" target="_blank" rel="noopener" href="<?= base_url('index.php?c=laboratory&a=printResult&id='.$order['id']) ?>">Cetak Laporan Hasil</a><?php endif; ?></div><?php endif; ?>
